// FIX56: Reversed original invoices always print their frozen pre-credit lines.
if(strtolower(trim((string)$inv->status))==='reversed' && Schema::hasTable('invoice_credit_notes')){
    $cn=DB::table('invoice_credit_notes')->where('invoice_id',$invoice)->first();
    if($cn){
        $snap=json_decode((string)$cn->original_snapshot,true,512,JSON_THROW_ON_ERROR);
        $job=(object)($snap['job']??(array)$job);
        $parts=collect(array_map(fn($row)=>(object)$row,$snap['parts']??[]));
        $labour=collect(array_map(fn($row)=>(object)$row,$snap['labour']??[]))
            ->filter(fn($row)=>(int)($row->billing_included??1)===1)->values();
    }
}
return compact('inv','job','parts','labour','ledger');
